<?php
declare(strict_types=1);
require __DIR__ . '/config.php';require __DIR__ . '/helpers.php';$profile=business_profile($pdo);$message='';$error='';$csrf=csrf_token();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??null);$action=(string)($_POST['action']??'add');try{if($action==='add'){$title=trim((string)($_POST['title']??''));$body=trim((string)($_POST['body']??''));if($title==='')throw new RuntimeException('Not başlığı boş olamaz.');if(text_length($title)>160||text_length($body)>1000)throw new RuntimeException('Not çok uzun.');$stmt=$pdo->prepare('INSERT INTO notes(title,body) VALUES(?,?)');$stmt->execute([$title,$body!==''?$body:null]);$message='Not panoya eklendi.';}elseif($action==='done'){$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if(!$id)throw new RuntimeException('Not bulunamadı.');$stmt=$pdo->prepare("UPDATE notes SET status='done',done_at=NOW() WHERE id=? AND status='active'");$stmt->execute([$id]);$message='Not tamamlandı olarak işaretlendi.';}}catch(Throwable $e){$error=$e->getMessage();}}
$notes=$pdo->query("SELECT * FROM notes WHERE status='active' ORDER BY created_at DESC")->fetchAll();
?>
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notlar • <?= e($profile['name']) ?></title><?php if($profile['logo_path']!==''):?><link rel="icon" href="<?= e($profile['logo_path']) ?>"><?php endif;?><link rel="stylesheet" href="assets/style.css?v=10.1"></head><body><header class="topbar"><div class="container topbar-inner"><a class="brand" href="home.php"><?php if($profile['logo_path']!==''):?><span class="brand-mark brand-mark-image"><img src="<?= e($profile['logo_path']) ?>" alt="Logo"></span><?php else:?><span class="brand-mark"><?= e(business_initials($profile['name'])) ?></span><?php endif;?><span><?= e($profile['name']) ?><small>Ortak Not Panosu</small></span></a><div class="nav-actions"><a class="btn btn-ghost" href="home.php">← Ana Ekran</a><a class="btn btn-ghost" href="orders.php">Adisyonlar</a><a class="btn" href="admin/notes.php">Not Arşivi</a></div></div></header><main class="standalone-page container"><section class="admin-heading"><div><div class="eyebrow">Ortak Pano</div><h1 class="admin-title">Notlar</h1><p class="muted">Gün içinde unutulmaması gereken işleri ve bilgileri buraya ekleyin.</p></div><span class="badge gold"><?= count($notes) ?> aktif not</span></section><?php if($message):?><div class="alert alert-success"><?= e($message) ?></div><?php endif;?><?php if($error):?><div class="alert alert-error"><?= e($error) ?></div><?php endif;?><section class="dashboard-grid"><div class="panel"><div class="panel-title"><div><div class="eyebrow">Yeni Not</div><h2>Not ekle</h2></div></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><input type="hidden" name="action" value="add"><label>Başlık<input name="title" required placeholder="Örn. Yarın süt siparişi verilecek"></label><label>Detay<textarea name="body" placeholder="İsteğe bağlı detay"></textarea></label><button class="btn btn-primary" type="submit">Notu Ekle</button></form></div><div class="panel"><div class="panel-title"><div><div class="eyebrow">Aktif</div><h2>Not panosu</h2></div></div><?php if(!$notes):?><div class="empty-receipt"><strong>Aktif not yok</strong><br><span>Yeni bir not ekleyebilirsiniz.</span></div><?php else:?><div class="note-board"><?php foreach($notes as $n):?><article class="note-card"><div><strong><?= e($n['title']) ?></strong><?php if(!empty($n['body'])):?><p><?= nl2br(e((string)$n['body'])) ?></p><?php endif;?><small><?= e(relative_time_tr($n['created_at'])) ?> • <?= e(date('d.m.Y H:i',strtotime($n['created_at']))) ?></small></div><form method="post"><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><input type="hidden" name="action" value="done"><input type="hidden" name="id" value="<?= (int)$n['id'] ?>"><button class="btn btn-success btn-sm">Tamamlandı</button></form></article><?php endforeach;?></div><?php endif;?></div></section></main><script src="assets/app.js?v=10"></script></body></html>
